body.script:
(async function() {


"use strict";

/* SVG foreignObject compatibility, modeled on DuckMath's wrapper. */
var __svgGetById = document.getElementById.bind(document);
document.getElementById = function(id) {
  return __svgGetById(id) || document.querySelector("[id='" + id + "']");
};
var __svgCreateElement = document.createElement.bind(document);
document.createElement = function(tag, options) {
  return document.createElementNS("http://www.w3.org/1999/xhtml", tag, options);
};
try {
  var __svgHead = document.querySelector("head");
  var __svgBody = document.querySelector("body");
  Object.defineProperty(document, "head", {
    get: function() { return __svgHead; },
    configurable: true
  });
  Object.defineProperty(document, "body", {
    get: function() { return __svgBody; },
    configurable: true
  });
} catch (e) {}


/*
 * Embedded Unity WebGL resources.
 * Each value is base64-encoded binary data.
 */
const __packedResources = "";
const __packedBinary = atob(__packedResources);
const __packedBytes = new Uint8Array(__packedBinary.length);
for (let i = 0; i < __packedBinary.length; i++) __packedBytes[i] = __packedBinary.charCodeAt(i);
if (typeof DecompressionStream === "undefined") {
  document.getElementById("svg-status-label").textContent = "This browser does not support gzip decompression.";
  throw new Error("DecompressionStream is unavailable");
}
const __jsonText = await new Response(new Blob([__packedBytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
const __UNITY_RESOURCES__ = JSON.parse(__jsonText);


function __b64ToBytes(s) {
    const bin = atob(s);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
}

function __resourceBlobURL(path) {
    // Normalize ./ and URL-ish paths.
    path = path.replace(/^\.\//, "").split("?")[0].split("#")[0];

    const r = __UNITY_RESOURCES__[path];
    if (!r) return null;

    const blob = new Blob([__b64ToBytes(r.data)], {type:r.mime});
    return URL.createObjectURL(blob);
}

/*
 * Replace the loader's normal resource paths with blob URLs.
 *
 * We first make a URL for the loader itself. Its relative imports/resources
 * are then intercepted by fetch/XHR where possible.
 */
const __loaderPath = "Build/Flappy Cat WebGL.loader.js";
const __loaderURL = __resourceBlobURL(__loaderPath);

if (!__loaderURL) {
    throw new Error("Embedded Unity loader was not found: " + __loaderPath);
}

/*
 * Patch fetch().
 */
const __nativeFetch = window.fetch.bind(window);
window.fetch = function(input, init) {
    let u = typeof input === "string" ? input : input.url;

    try {
        const url = new URL(u, document.baseURI);
        const key = url.pathname.replace(/^\//, "");

        const blobURL = __resourceBlobURL(key);
        if (blobURL) {
            return __nativeFetch(blobURL, init);
        }
    } catch (e) {}

    return __nativeFetch(input, init);
};

/*
 * Patch XMLHttpRequest for Unity versions that use XHR.
 */
const __NativeXHR = window.XMLHttpRequest;

class __EmbeddedXHR extends __NativeXHR {
    open(method, url, ...rest) {
        let rewritten = url;

        try {
            const u = new URL(url, document.baseURI);
            const key = u.pathname.replace(/^\//, "");
            const blobURL = __resourceBlobURL(key);
            if (blobURL) rewritten = blobURL;
        } catch (e) {}

        return super.open(method, rewritten, ...rest);
    }
}

window.XMLHttpRequest = __EmbeddedXHR;

/*
 * Dynamically load Unity's loader.
 */
const s = document.createElement("script");
s.src = __loaderURL;
s.onload = () => {
    /*
     * Unity's loader API is normally exposed as createUnityInstance().
     * The exact config keys vary slightly between Unity versions, so we
     * discover the generated build files from the embedded resource table.
     */
    const loaderBase = __loaderURL;

    const names = Object.keys(__UNITY_RESOURCES__);

    const wasm = names.find(x => /\.wasm(?:\.unityweb)?$/i.test(x));
    const data = names.find(x => /\.data(?:\.unityweb)?$/i.test(x));
    const framework = names.find(x => /\.framework\.js(?:\.unityweb)?$/i.test(x));

    const config = {
        dataUrl: data ? __resourceBlobURL(data) : undefined,
        frameworkUrl: framework ? __resourceBlobURL(framework) : undefined,
        codeUrl: wasm ? __resourceBlobURL(wasm) : undefined,
        streamingAssetsUrl: "StreamingAssets",
        companyName: "Embedded",
        productName: "Embedded Unity WebGL Game",
        productVersion: "1.0",
        matchWebGLToCanvasSize: true,
        devicePixelRatio: 1
    };

    if (typeof createUnityInstance !== "function") {
        document.body.insertAdjacentHTML(
            "beforeend",
            "<pre style='color:white;padding:20px'>Unity loader loaded, "
            + "but createUnityInstance() was not found.</pre>"
        );
        return;
    }

    createUnityInstance(
        document.querySelector("#unity-canvas"),
        config,
        progress => {
          var panel = document.getElementById("svg-status");
          var label = document.getElementById("svg-status-label");
          if (label) label.textContent = "Loading Unity… " + Math.round(progress * 100) + "%";
          if (panel) panel.style.display = "flex";
          console.log("Unity loading:", progress);
        }
    ).then(() => {
        var panel = document.getElementById("svg-status");
        if (panel) panel.style.display = "none";
    }).catch(err => {
        console.error(err);
        document.body.insertAdjacentHTML(
            "beforeend",
            "<pre style='position:fixed;left:0;top:0;color:white;"
            + "background:#400;padding:10px;z-index:99999'>"
            + String(err) + "</pre>"
        );
    });
};

s.onerror = () => {
    document.body.insertAdjacentHTML(
        "beforeend",
        "<pre style='color:white;padding:20px'>"
        + "Could not load the embedded Unity loader.</pre>"
    );
};

document.head.appendChild(s);


})();
